ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns ns0 http://tempuri.org/
ns ns01 http://www.etb.com.co/orquestador
ns ns02 http://schemas.xmlsoap.org/soap/envelope/
---
{
		ns0#ConsultarInventario: {
			ns0#solicitudInventario: {
				ns01#Encabezado: {
					ns01#Sistema: {
						ns01#IdCorrelacion: vars.RequestAttributes.uriParams.idServiceAccount,
						ns01#Nombre: p('inventory.servidor'),
						ns01#Servidor: p('inventory.servidor')
					}
				},
				ns01#DatosSolicitud: {
					ns01#IdCuentaServicio: vars.RequestAttributes.uriParams.idServiceAccount,
					ns01#Inerno:false,
					ns01#Tecnologia: p('inventory.tecnologia'),
					ns01#Actualizar: true
				}
			}
		}
}
